function addSurcharge(table, surcharge) {
  const out = {};
  for (const [w, zones] of Object.entries(table)) {
    out[w] = {};
    for (const [z, r] of Object.entries(zones)) {
      out[w][z] = +(r + surcharge).toFixed(2);
    }
  }
  return out;
}

