function lookupDomesticRate(serviceKey, zone, billableWeight) {
  const table = RATE_TABLES[serviceKey];
  if (!table) return null;

  const zs = String(zone);
  const w = Math.ceil(billableWeight);

  if (w > 150) {
    const base = table['150'];
    const perLb = table['151'];
    if (!base || !perLb || base[zs] === undefined || perLb[zs] === undefined) return null;
    return +(base[zs] + (w - 150) * perLb[zs]).toFixed(2);
  }

  if (table[w] && table[w][zs] !== undefined) return table[w][zs];

  const weights = Object.keys(table)
    .map(Number)
    .filter(n => n <= 150)
    .sort((a, b) => a - b);

  for (let i = weights.length - 1; i >= 0; i--) {
    if (weights[i] < w && table[weights[i]][zs] !== undefined) {
      const lo = weights[i];
      const loRate = table[lo][zs];
      const hi = weights.find(x => x > lo && table[x] && table[x][zs] !== undefined);
      if (!hi) return loRate;
      const hiRate = table[hi][zs];
      return +(loRate + ((w - lo) / (hi - lo)) * (hiRate - loRate)).toFixed(2);
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// DOMESTIC CALCULATOR COMPONENT
// ---------------------------------------------------------------------------
function DomesticCalculator() {
  const [selectedService, setSelectedService] = useState('gc');
  const [weight, setWeight] = useState('');
  const [zip, setZip] = useState('');
  const [qty, setQty] = useState('1');
  const [dimL, setDimL] = useState('');
  const [dimW, setDimW] = useState('');
  const [dimH, setDimH] = useState('');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleServiceSelect = useCallback((key) => {
    setSelectedService(key);
    setResult(null);
    setError('');
  }, []);

  const calculate = useCallback(() => {
    setError('');
    setResult(null);

    const wt = parseFloat(weight);
    if (!wt || wt <= 0) { setError('Enter the actual package weight.'); return; }
    if (!zip || zip.length < 5) { setError('Enter a valid 5-digit destination ZIP code.'); return; }

    const groundZone = ZIP_ZONES[zip.substring(0, 3)];
    if (!groundZone) { setError('ZIP prefix not found in zone chart. Please verify the destination ZIP code.'); return; }

    const svc = DOMESTIC_SERVICES.find(s => s.key === selectedService);
    const serviceZone = svc.zoneBase === 0 ? groundZone : svc.zoneBase + groundZone;

    const quantity = Math.max(1, parseInt(qty) || 1);

    const l = parseFloat(dimL) || 0;
    const w2 = parseFloat(dimW) || 0;
    const h = parseFloat(dimH) || 0;
    const dimWeight = (l > 0 && w2 > 0 && h > 0) ? (l * w2 * h) / 166 : 0;
    const billableWeight = Math.max(wt, dimWeight);
    const dimApplied = dimWeight > wt;

    const rate = lookupDomesticRate(selectedService, serviceZone, billableWeight);
    if (rate === null) {
      setError(`Zone ${serviceZone} is not available for ${svc.label} (${svc.sub}).`);
      return;
    }

    const totalCombinedWeight = billableWeight * quantity;
    const hwtEligible = quantity > 1
      && totalCombinedWeight >= 200
      && (selectedService === 'gc' || selectedService === 'gr');

    const isResidential = selectedService.endsWith('-r') || selectedService === 'gr';
    const resSurcharge = isResidential
      ? (selectedService === 'gr' || selectedService === '3ds-r' ? 3.55 : 4.00)
      : 0;

    const ahWeight = wt > 70 ? 27.75 : 0;
    const longestSide = Math.max(l, w2, h);
    const secondLongest = [l, w2, h].sort((a, b) => b - a)[1];
    const hasDims = l > 0 && w2 > 0 && h > 0;
    const ahOther = hasDims && longestSide > 48 ? 17.50 : 0;
    const shortestSide = Math.min(l, w2, h);
    const girth = hasDims ? 2 * (secondLongest + shortestSide) : 0;
    const lps = hasDims && (longestSide > 96 || (longestSide + girth) > 130) ? 105.50 : 0;
    const ahOtherFinal = lps > 0 ? 0 : ahOther;

    const surchargesPerPkg = resSurcharge + ahWeight + ahOtherFinal + lps;
    const totalPerPkg = +(rate + surchargesPerPkg).toFixed(2);
    const grandTotal = +(totalPerPkg * quantity).toFixed(2);

    const surchargeLines = [
      resSurcharge > 0 && { label: 'Residential surcharge', amount: resSurcharge, note: selectedService === 'gr' || selectedService === '3ds-r' ? 'Ground discounted rate' : 'Air discounted rate' },
      ahWeight > 0  && { label: 'Additional Handling – Weight', amount: ahWeight, note: `Actual weight ${wt} lbs > 70 lbs threshold` },
      ahOtherFinal > 0 && { label: 'Additional Handling – Size', amount: ahOtherFinal, note: `Longest side ${longestSide}" > 48"` },
      lps > 0       && { label: 'Large Package Surcharge', amount: lps, note: longestSide > 96 ? `Longest side ${longestSide}" > 96"` : `Length + girth ${(longestSide + girth).toFixed(0)}" > 130"` },
    ].filter(Boolean);

    setResult({
      rate,
      totalPerPkg,
      grandTotal,
      surchargesPerPkg,
      surchargeLines,
      quantity,
      billableWeight,
      totalCombinedWeight,
      actualWeight: wt,
      dimWeight,
      dimApplied,
      longestSide: hasDims ? longestSide : null,
      hwtEligible,
      groundZone,
      serviceZone,
      zoneName: ZONE_NAMES[groundZone] || `Zone ${groundZone}`,
      svc,
      isResidential,
      resSurcharge,
    });
  }, [weight, zip, qty, dimL, dimW, dimH, selectedService]);

  const handleKeyDown = (e) => { if (e.key === 'Enter') calculate(); };

  return (
    <div>
      <p style={{ fontSize: '10px', fontWeight: 600, color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '12px', fontFamily: theme.mono }}>
        Service Level
      </p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '10px', marginBottom: '30px' }}>
        {DOMESTIC_SERVICES.map(svc => {
          const isActive = selectedService === svc.key;
          return (
            <button
              key={svc.key}
              onClick={() => handleServiceSelect(svc.key)}
              style={{
                textAlign: 'left',
                padding: '12px 16px',
                borderRadius: '2px',
                border: isActive ? `1px solid ${theme.brass}` : `1px solid ${theme.line}`,
                backgroundColor: isActive ? theme.paper2 : '#fff',
                cursor: 'pointer',
                transition: 'all 0.2s',
                boxShadow: isActive ? '0 2px 8px rgba(0,0,0,0.04)' : 'none'
              }}
              onMouseOver={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.brass }}
              onMouseOut={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.line }}
            >
              <div style={{ fontWeight: 500, fontSize: '0.9rem', color: theme.ink, marginBottom: '4px' }}>{svc.label}</div>
              <div style={{ fontSize: '0.75rem', color: theme.inkSoft }}>{svc.sub}</div>
            </button>
          )
        })}
      </div>

      <p style={{ fontSize: '10px', fontWeight: 600, color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '12px', fontFamily: theme.mono }}>
        Package Details
      </p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '16px', marginBottom: '20px' }}>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Actual Wt (lbs)</label>
          <input
            type="number" min="0.1" step="0.1" value={weight} onChange={e => setWeight(e.target.value)} onKeyDown={handleKeyDown}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Quantity</label>
          <input
            type="number" min="1" step="1" value={qty} onChange={e => setQty(e.target.value)} onKeyDown={handleKeyDown}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Dest. ZIP</label>
          <input
            type="text" maxLength={5} value={zip} onChange={e => setZip(e.target.value.replace(/\D/g, ''))} onKeyDown={handleKeyDown}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Address Type</label>
          <select
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '0.9rem', backgroundColor: '#fff', outline: 'none', boxSizing: 'border-box', cursor: 'pointer', fontFamily: theme.sans, color: theme.ink }}
            onChange={e => {
              const isRes = e.target.value === 'residential';
              const current = DOMESTIC_SERVICES.find(s => s.key === selectedService);
              if (!current) return;
              if (isRes && current.com === true) {
                const resVariant = selectedService.replace('-c', '-r').replace(/^gc$/, 'gr').replace(/^3ds-c$/, '3ds-r').replace(/^2da-c$/, '2da-r').replace(/^ndas-c$/, 'ndas-r').replace(/^nda-c$/, 'nda-r');
                if (DOMESTIC_SERVICES.find(s => s.key === resVariant)) setSelectedService(resVariant);
              } else if (!isRes && current.com === false) {
                const comVariant = selectedService.replace('-r', '-c').replace(/^gr$/, 'gc').replace(/^3ds-r$/, '3ds-c').replace(/^2da-r$/, '2da-c').replace(/^ndas-r$/, 'ndas-c').replace(/^nda-r$/, 'nda-c');
                if (DOMESTIC_SERVICES.find(s => s.key === comVariant)) setSelectedService(comVariant);
              }
            }}
            value={DOMESTIC_SERVICES.find(s => s.key === selectedService)?.com === false ? 'residential' : 'commercial'}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          >
            <option value="commercial">Commercial</option>
            <option value="residential">Residential</option>
          </select>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px', marginBottom: '8px' }}>
        {[['dimL', dimL, setDimL, 'Length (in)'], ['dimW', dimW, setDimW, 'Width (in)'], ['dimH', dimH, setDimH, 'Height (in)']].map(([id, val, setter, lbl]) => (
          <div key={id}>
            <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>{lbl}</label>
            <input
              type="number" min="0" step="0.5" value={val} onChange={e => setter(e.target.value)} onKeyDown={handleKeyDown} placeholder="0"
              style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
              onFocus={(e) => e.target.style.borderColor = theme.brass}
              onBlur={(e) => e.target.style.borderColor = theme.line}
            />
          </div>
        ))}
      </div>
      <p style={{ fontSize: '0.75rem', color: theme.inkSoft, marginBottom: '30px' }}>
        DIM divisor: <strong style={{ color: theme.ink }}>166</strong> (Contract rate). Leave blank to skip dimensional / large package checks.
      </p>

      <button
        onClick={calculate}
        style={{ width: '100%', padding: '16px', background: theme.ink, color: '#fff', fontSize: '11px', letterSpacing: '0.15em', textTransform: 'uppercase', fontFamily: theme.mono, border: 'none', cursor: 'pointer', transition: 'background 0.2s', borderRadius: '2px' }}
        onMouseOver={(e) => e.currentTarget.style.background = theme.brass}
        onMouseOut={(e) => e.currentTarget.style.background = theme.ink}
      >
        Calculate Expected Cost
      </button>

      {error && (
        <div style={{ marginTop: '20px', padding: '16px', backgroundColor: '#fff', border: `1px solid ${theme.brass}`, color: theme.ink, fontSize: '0.85rem', borderRadius: '2px' }}>
          {error}
        </div>
      )}

      {result && (
        <div style={{ marginTop: '30px', padding: '30px', backgroundColor: '#fff', border: `1px solid ${theme.line}`, borderRadius: '2px', boxShadow: '0 4px 24px rgba(0,0,0,0.02)' }}>
          <p style={{ fontSize: '0.85rem', color: theme.inkSoft, margin: '0 0 10px 0', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            {result.svc.label} · {result.svc.sub}
          </p>

          <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', marginBottom: '10px', flexWrap: 'wrap' }}>
            {result.quantity > 1 ? (
              <>
                <span style={{ fontSize: '2.5rem', fontFamily: theme.serif, color: theme.ink, lineHeight: 1 }}>${result.grandTotal.toFixed(2)}</span>
                <span style={{ fontSize: '0.9rem', color: theme.inkSoft }}>total ({result.quantity} pkgs)</span>
                <span style={{ fontSize: '1.2rem', color: theme.inkSoft, marginLeft: 'auto' }}>${result.totalPerPkg.toFixed(2)} <span style={{ fontSize: '0.8rem' }}>/ea</span></span>
              </>
            ) : (
              <>
                <span style={{ fontSize: '2.5rem', fontFamily: theme.serif, color: theme.ink, lineHeight: 1 }}>${result.totalPerPkg.toFixed(2)}</span>
                <span style={{ fontSize: '0.9rem', color: theme.inkSoft }}>net cost per package</span>
              </>
            )}
          </div>

          <p style={{ fontSize: '0.75rem', color: theme.inkSoft, margin: '0 0 20px 0' }}>
            Includes 7% discount from Small Business Rates {result.quantity > 1 && ` · Each package rated individually`}
          </p>

          {result.surchargesPerPkg > 0 && (
            <div style={{ marginBottom: '20px', backgroundColor: '#fff', border: `1px solid ${theme.line}`, borderRadius: '2px', overflow: 'hidden' }}>
              <div style={{ padding: '8px 16px', backgroundColor: theme.paper2, borderBottom: `1px solid ${theme.line}` }}>
                <span style={{ fontSize: '0.7rem', fontWeight: 600, color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.05em', fontFamily: theme.mono }}>Cost breakdown per package</span>
              </div>
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 16px', fontSize: '0.85rem', borderBottom: `1px solid ${theme.paper2}` }}>
                  <span style={{ color: theme.inkSoft }}>Base transportation rate</span>
                  <span style={{ fontWeight: 500, color: theme.ink }}>${result.rate.toFixed(2)}</span>
                </div>
                {result.surchargeLines.map(({ label, amount, note }) => (
                  <div key={label} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', padding: '10px 16px', fontSize: '0.85rem', borderBottom: `1px solid ${theme.paper2}` }}>
                    <div>
                      <span style={{ color: theme.inkSoft }}>{label}</span>
                      {note && <div style={{ fontSize: '0.75rem', color: theme.brass, marginTop: '2px' }}>{note}</div>}
                    </div>
                    <span style={{ fontWeight: 500, color: theme.ink, marginLeft: '16px', flexShrink: 0 }}>+${amount.toFixed(2)}</span>
                  </div>
                ))}
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 16px', fontSize: '0.85rem', fontWeight: 600, backgroundColor: theme.paper2 }}>
                  <span style={{ color: theme.ink }}>Total per package</span>
                  <span style={{ color: theme.ink }}>${result.totalPerPkg.toFixed(2)}</span>
                </div>
                {result.quantity > 1 && (
                  <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 16px', fontSize: '0.85rem', fontWeight: 600, borderTop: `2px solid ${theme.line}` }}>
                    <span style={{ color: theme.ink }}>Total × {result.quantity} packages</span>
                    <span style={{ color: theme.ink }}>${result.grandTotal.toFixed(2)}</span>
                  </div>
                )}
              </div>
            </div>
          )}

          {result.dimApplied && (
            <div style={{ marginBottom: '16px', padding: '12px 16px', backgroundColor: theme.paper2, borderLeft: `3px solid ${theme.brass}`, fontSize: '0.8rem', color: theme.ink }}>
              <strong>Note:</strong> Dimensional weight ({result.dimWeight.toFixed(1)} lbs) exceeds actual weight ({result.actualWeight} lbs). Billed at DIM weight.
            </div>
          )}

          {result.hwtEligible && (
            <div style={{ marginBottom: '16px', padding: '12px 16px', backgroundColor: theme.paper, border: `1px solid ${theme.line}`, fontSize: '0.8rem', color: theme.ink }}>
              <strong>Hundredweight (HWT) Eligible:</strong> {result.quantity} packages totaling {result.totalCombinedWeight.toFixed(0)} lbs to the same address qualifies for Tier 06 HWT pricing. Check HWT charts for potential savings over the per-package rate.
            </div>
          )}

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '16px', marginTop: '20px', paddingTop: '20px', borderTop: `1px solid ${theme.line}` }}>
            {[
              ['Billable Wt', `${result.billableWeight.toFixed(1)} lbs`],
              result.quantity > 1 ? ['Total Wt', `${result.totalCombinedWeight.toFixed(0)} lbs`] : ['Zone Code', result.zoneName],
              ['Service Zone', `Zone ${result.serviceZone}`],
              ['Fuel Surcharge', 'Waived']
            ].map(([label, value], idx) => (
              <div key={idx}>
                <p style={{ margin: '0 0 4px 0', fontSize: '0.7rem', color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.05em', fontFamily: theme.mono }}>{label}</p>
                <p style={{ margin: 0, fontSize: '1rem', color: theme.ink, fontWeight: 500 }}>{value}</p>
              </div>
            ))}
          </div>

          <div style={{ marginTop: '24px', paddingTop: '16px', borderTop: `1px dotted ${theme.line}`, fontSize: '0.75rem', color: theme.inkSoft, lineHeight: 1.5 }}>
            <span style={{ color: theme.ink, fontWeight: 500 }}>Contract surcharges applied when triggered:</span> Residential ($3.55 Ground / $4.00 Air) · Additional Handling – Weight $27.75 (actual wt &gt; 70 lbs) · Additional Handling – Size $17.50 (longest side &gt; 48") · Large Package $105.50 (longest side &gt; 96" or L+girth &gt; 130")
            <br /><br />
            <span style={{ color: theme.ink, fontWeight: 500 }}>Permanently Waived Surcharges:</span> Fuel Surcharge · Delivery Area Surcharge (DAS) · Address Correction · 3rd-Party Billing · 2 lb Weight Variance
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// INTERNATIONAL CALCULATOR COMPONENT
// ---------------------------------------------------------------------------
function IntlCalculator() {
  const [direction, setDirection]   = useState('export');
  const [svcKey,    setSvcKey]      = useState('wwe_exp');
  const [region,    setRegion]      = useState('');
  const [container, setContainer]   = useState('Pkg');
  const [weight,    setWeight]      = useState('');
  const [qty,       setQty]         = useState('1');
  const [result,    setResult]      = useState(null);
  const [error,     setError]       = useState('');

  const svc = INTL_SERVICES[direction].find(s => s.key === svcKey)
           || INTL_SERVICES[direction][0];

  const regionList = useCallback(() => {
    if (svc.caOnly) return direction === 'export' ? CA_REGIONS : FROM_CA_REGIONS;
    if (svc.mxOnly) return direction === 'export' ? MX_REGIONS : FROM_MX_REGIONS;
    return direction === 'export' ? EXPORT_REGIONS : IMPORT_REGIONS;
  }, [svc, direction])();

  const handleDirectionChange = (dir) => {
    setDirection(dir);
    setSvcKey(dir === 'export' ? 'wwe_exp' : 'wwe_imp');
    setRegion('');
    setResult(null);
    setError('');
  };

  const handleSvcChange = (key) => {
    setSvcKey(key);
    setRegion('');
    setResult(null);
    setError('');
  };

  const getZone = useCallback((regionLabel) => {
    const r = regionList.find(x => x.label === regionLabel);
    if (!r) return null;
    if (r.zone !== undefined) return r.zone;
    
    if (svc.key.startsWith('wwex')) return r.wwex ?? null;
    if (svc.key.startsWith('wws')) return r.wws ?? null;
    if (svc.key.startsWith('wwe')) return r.wwe ?? null;
    
    return null;
  }, [regionList, svc]);

  const calculate = useCallback(() => {
    setError(''); setResult(null);
    const wt = parseFloat(weight);
    if (!wt || wt <= 0) { setError('Enter the package weight.'); return; }
    if (!region)        { setError('Select a destination region.'); return; }

    const zone = getZone(region);
    if (!zone) {
      setError(`${svc.label} does not serve "${region}". Try a different service level.`);
      return;
    }

    const availableContainers = Object.keys(INTL_RATES[svc.key] || {});
    const ct = availableContainers.includes(container) ? container : availableContainers[0];

    const quantity = Math.max(1, parseInt(qty) || 1);
    const bw = Math.ceil(wt);
    const rate = lookupIntlRate(svc.key, ct, zone, bw);

    if (rate === null) {
      setError(`No rate found for ${svc.label} to "${region}" at ${bw} lbs. This weight/destination combination may not be available.`);
      return;
    }

    setResult({
      rate,
      totalRate: +(rate * quantity).toFixed(2),
      quantity,
      weight: bw,
      zone,
      region,
      svc,
      ct,
      availableContainers,
    });
  }, [weight, region, container, qty, svc, getZone]);

  const handleKeyDown = (e) => { if (e.key === 'Enter') calculate(); };

  return (
    <div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '10px', marginBottom: '24px' }}>
        {[
          ['export', 'Shipping OUT (Export)'],
          ['import', 'Receiving IN (Import)']
        ].map(([dir, label]) => {
          const isActive = direction === dir;
          return (
             <button
              key={dir}
              onClick={() => handleDirectionChange(dir)}
              style={{
                textAlign: 'center',
                padding: '12px 16px',
                borderRadius: '2px',
                border: isActive ? `1px solid ${theme.brass}` : `1px solid ${theme.line}`,
                backgroundColor: isActive ? theme.paper2 : '#fff',
                cursor: 'pointer',
                transition: 'all 0.2s',
                boxShadow: isActive ? '0 2px 8px rgba(0,0,0,0.04)' : 'none',
                fontWeight: 500, fontSize: '0.85rem', color: theme.ink, fontFamily: theme.sans
              }}
              onMouseOver={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.brass }}
              onMouseOut={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.line }}
            >
              {label}
            </button>
          )
        })}
      </div>

      <p style={{ fontSize: '10px', fontWeight: 600, color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '12px', fontFamily: theme.mono }}>
        Service Level
      </p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '10px', marginBottom: '30px' }}>
        {INTL_SERVICES[direction].map(s => {
          const isActive = svcKey === s.key;
          return (
            <button
              key={s.key}
              onClick={() => handleSvcChange(s.key)}
              style={{
                textAlign: 'left',
                padding: '12px 16px',
                borderRadius: '2px',
                border: isActive ? `1px solid ${theme.brass}` : `1px solid ${theme.line}`,
                backgroundColor: isActive ? theme.paper2 : '#fff',
                cursor: 'pointer',
                transition: 'all 0.2s',
                boxShadow: isActive ? '0 2px 8px rgba(0,0,0,0.04)' : 'none'
              }}
              onMouseOver={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.brass }}
              onMouseOut={(e) => { if(!isActive) e.currentTarget.style.borderColor = theme.line }}
            >
              <div style={{ fontWeight: 500, fontSize: '0.9rem', color: theme.ink, marginBottom: '4px' }}>{s.label}</div>
              <div style={{ fontSize: '0.75rem', color: theme.inkSoft }}>{s.sub}</div>
            </button>
          )
        })}
      </div>

      <p style={{ fontSize: '10px', fontWeight: 600, color: theme.inkSoft, textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '12px', fontFamily: theme.mono }}>
        {direction === 'export' ? 'Destination' : 'Origin'} Details
      </p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '16px', marginBottom: '16px' }}>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>
            {direction === 'export' ? 'Destination Region' : 'Origin Region'}
          </label>
          <select
            value={region}
            onChange={e => { setRegion(e.target.value); setResult(null); }}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '0.9rem', backgroundColor: '#fff', outline: 'none', boxSizing: 'border-box', cursor: 'pointer', fontFamily: theme.sans, color: theme.ink }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          >
            <option value="">Select region…</option>
            {regionList.map(r => {
              let zone = null;
              if (r.zone !== undefined) zone = r.zone;
              else if (svc.key.startsWith('wwex')) zone = r.wwex;
              else if (svc.key.startsWith('wws')) zone = r.wws;
              else if (svc.key.startsWith('wwe')) zone = r.wwe;
              
              return (
                <option key={r.label} value={r.label} disabled={!zone}>
                  {r.label}{!zone ? ' (not served)' : ''}
                </option>
              );
            })}
          </select>
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Container Type</label>
          <select
            value={container}
            onChange={e => setContainer(e.target.value)}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '0.9rem', backgroundColor: '#fff', outline: 'none', boxSizing: 'border-box', cursor: 'pointer', fontFamily: theme.sans, color: theme.ink }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          >
            {CONTAINER_TYPES.map(ct => {
              const available = Object.keys(INTL_RATES[svcKey] || {}).includes(ct.key);
              return (
                <option key={ct.key} value={ct.key} disabled={!available}>
                  {ct.label}{!available ? ' (N/A)' : ''}
                </option>
              );
            })}
          </select>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '16px', marginBottom: '30px' }}>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Weight (lbs)</label>
          <input
            type="number" min="0.1" step="0.1" value={weight}
            onChange={e => setWeight(e.target.value)} onKeyDown={handleKeyDown}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '0.8rem', color: theme.inkSoft, marginBottom: '6px' }}>Number of packages</label>
          <input
            type="number" min="1" step="1" value={qty}
            onChange={e => setQty(e.target.value)} onKeyDown={handleKeyDown}
            style={{ width: '100%', padding: '10px', border: `1px solid ${theme.line}`, borderRadius: '2px', fontSize: '1rem', fontFamily: theme.mono, outline: 'none', boxSizing: 'border-box' }}
            onFocus={(e) => e.target.style.borderColor = theme.brass}
            onBlur={(e) => e.target.style.borderColor = theme.line}
          />
        </div>
      </div>

      <button
        onClick={calculate}
        style={{ width: '100%', padding: '16px', background: theme.ink, color: '#fff', fontSize: '11px', letterSpacing: '0.15em', textTransform: 'uppercase', fontFamily: theme.mono, border: 'none', cursor: 'pointer', transition: 'background 0.2s', borderRadius: '2px' }}
        onMouseOver={(e) => e.currentTarget.style.background = theme.brass}
        onMouseOut={(e) => e.currentTarget.style.background = theme.ink}
      >
        Calculate Expected Cost
      </button>

      {error && (
        <div style={{ marginTop: '20px', padding: '16px', backgroundColor: '#fff', border: `1px solid ${theme.brass}`, color: theme.ink, fontSize: '0.85rem', borderRadius: '2px' }}>
          {error}
        </div>
      )}

      {result && (
        <div style={{ marginTop: '30px', padding: '30px', backgroundColor: '#fff', border: `1px solid ${theme.line}`, borderRadius: '2px', boxShadow: '0 4px 24px rgba(0,0,0,0.02)' }}>
          <p style={{ fontSize: '0.85rem', color: theme.inkSoft, margin: '0 0 10px 0', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            {result.svc.label} · {result.svc.sub}
          </p>
          <p style={{ fontSize: '0.75rem', color: theme.inkSoft, margin: '0 0 20px 0' }}>
            {result.region} · {result.ct === 'Pkg' ? 'Package' : result.ct === 'Doc' ? 'Document' : result.ct === 'Ltr' ? 'Letter' : 'Express Pak'} · Zone {result.zone}
          </p>

          <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', marginBottom: '10px', flexWrap: 'wrap' }}>
            {result.quantity > 1 ? (
              <>
                <span style={{ fontSize: '2.5rem', fontFamily: theme.serif, color: theme.ink, lineHeight: 1 }}>${result.totalRate.toFixed(2)}</span>
                <span style={{ fontSize: '0.9rem', color: theme.inkSoft }}>total ({result.quantity} pkgs)</span>
                <span style={{ fontSize: '1.2rem', color: theme.inkSoft, marginLeft: 'auto' }}>${result.rate.toFixed(2)} <span style={{ fontSize: '0.8rem' }}>/ea</span></span>
              </>
            ) : (
              <>
                <span style={{ fontSize: '2.5rem', fontFamily: theme.serif, color: theme.ink, lineHeight: 1 }}>${result.rate.toFixed(2)}</span>
                <span style={{ fontSize: '0.9rem', color: theme.inkSoft }}>net shipping cost</span>
              </>
            )}
          </div>

          <p style={{ fontSize: '0.75rem', color: theme.inkSoft, margin: '0 0 20px 0' }}>
            Contract D001305131 · 7% discount applied · {result.weight} lb{result.weight !== 1 ? 's' : ''} billable weight
          </p>

          <div style={{ marginTop: '24px', paddingTop: '16px', borderTop: `1px dotted ${theme.line}`, fontSize: '0.75rem', color: theme.inkSoft, lineHeight: 1.5 }}>
            <strong style={{ color: theme.ink, fontWeight: 500 }}>Note:</strong> International rates are per shipment. Zone assignment uses standard UPS international zone structure — confirm specific country routing with your UPS rep for exact billing.
            <br /><br />
            <strong style={{ color: theme.ink, fontWeight: 500 }}>Permanently Waived Surcharges:</strong> Fuel Surcharge · 3rd-party billing surcharge
          </div>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// MAIN EXPORT (TABBED WRAPPER)
